import java.util.*;
public class BrokenHashKeyDemo {
  public static void main(String[] args) {
    class Key { String id; Key(String id){this.id=id;} public boolean equals(Object o){return o instanceof Key k && id.equals(k.id);} }
    var map = new java.util.HashMap<Key,String>(); map.put(new Key("P1"),"ok");
    System.out.println(map.get(new Key("P1")));
  }
}
